-- Create Concept table
CREATE TABLE BH_Concept (
	AD_Client_ID numeric(10) NOT NULL, 
	AD_Org_ID numeric(10) NOT NULL, 
	bh_concept_class VARCHAR(50) DEFAULT NULL, 
	BH_Concept_ID numeric(10) NOT NULL, 
	BH_Concept_Type VARCHAR(100) DEFAULT NULL, 
	BH_Concept_UU VARCHAR(36) DEFAULT NULL, 
	BH_Display_Locale VARCHAR(100) DEFAULT NULL,
	BH_Display_Name VARCHAR(100) DEFAULT NULL,
	BH_ExternalID VARCHAR(100) DEFAULT NULL, 
	BH_OclID VARCHAR(100) DEFAULT NULL,
	BH_Owner VARCHAR(100) DEFAULT NULL, 
	BH_Source VARCHAR(100) DEFAULT NULL, 
	Created timestamp DEFAULT NOW(), 
	CreatedBy numeric(10) DEFAULT NULL, 
	BH_Data_Type VARCHAR(100) DEFAULT NULL,
	Description VARCHAR(2000) DEFAULT NULL, 
	IsActive CHAR(1) DEFAULT 'Y' CHECK (IsActive IN ('Y','N')), 
	Updated timestamp DEFAULT NOW(), 
	UpdatedBy numeric(10) DEFAULT NULL, 
	URL VARCHAR(120) DEFAULT NULL, 
	
	CONSTRAINT BH_Concept_Key PRIMARY KEY (BH_Concept_ID), 
	CONSTRAINT BH_Concept_UU_idx UNIQUE (BH_Concept_UU)
);

