-- Create Concept Mapping table
CREATE TABLE BH_Concept_Mapping (
    AD_Client_ID numeric(10) DEFAULT NULL,
    AD_Org_ID numeric(10) DEFAULT NULL,
    BH_Concept_ID numeric(10) NOT NULL,
    BH_Concept_Mapping_ID numeric(10) DEFAULT NULL,
    BH_Concept_Mapping_UU VARCHAR(36) DEFAULT NULL,
    BH_ExternalID VARCHAR(100) DEFAULT NULL,
    BH_From_Concept_Code VARCHAR(100) DEFAULT NULL,
    BH_From_Concept_Name VARCHAR(255) DEFAULT NULL,
    BH_From_Concept_Name_Resolved VARCHAR(255) DEFAULT NULL,
    BH_From_Concept_Url VARCHAR(255) DEFAULT NULL,
    BH_Map_Type VARCHAR(50) DEFAULT NULL,
    BH_OclID VARCHAR(100) DEFAULT NULL,
    BH_Owner VARCHAR(100) DEFAULT NULL,
    BH_Source VARCHAR(100) DEFAULT NULL,
    BH_To_Concept_Code VARCHAR(100) DEFAULT NULL,
    BH_To_Concept_Name VARCHAR(255) DEFAULT NULL,
    BH_To_Concept_Name_Resolved VARCHAR(255) DEFAULT NULL,
    BH_To_Concept_Url VARCHAR(255) DEFAULT NULL,
    BH_To_Source_Name VARCHAR(255) DEFAULT NULL,
    Created timestamp DEFAULT NOW(),
    CreatedBy numeric(10) DEFAULT NULL ,
    IsActive CHAR(1) DEFAULT 'Y' CHECK (IsActive IN ('Y','N')),
    Updated timestamp DEFAULT NOW(),
    UpdatedBy numeric(10) DEFAULT NULL ,

    CONSTRAINT BH_Concept_Mapping_Key PRIMARY KEY (BH_Concept_Mapping_ID),
    CONSTRAINT BH_Concept_Mapping_UU_idx UNIQUE (BH_Concept_Mapping_UU),
    CONSTRAINT BHConcept_BHConceptMapping FOREIGN KEY (BH_Concept_ID) REFERENCES bh_concept(bh_concept_id) DEFERRABLE INITIALLY DEFERRED
);

